function useFormBuilder() {
	const [state, dispatch] = useReducer(builderReducer, initialState);
	const actions = useMemo(() => ({
		loadDefinition: (definition) => dispatch({
			type: "load",
			definition
		}),
		setTitle: (title) => dispatch({
			type: "setTitle",
			title
		}),
		setDescription: (description) => dispatch({
			type: "setDescription",
			description
		}),
		addField: (fieldType, index) => dispatch({
			type: "addField",
			fieldType,
			index
		}),
		duplicateField: (id) => dispatch({
			type: "duplicateField",
			id
		}),
		removeField: (id) => dispatch({
			type: "removeField",
			id
		}),
		moveField: (id, direction) => dispatch({
			type: "moveField",
			id,
			direction
		}),
		updateField: (id, patch) => dispatch({
			type: "updateField",
			id,
			patch
		}),
		selectField: (id) => dispatch({
			type: "selectField",
			id
		})
	}), []);
	const getDefinition = useCallback(() => ({
		title: state.title.trim() || "Untitled form",
		description: state.description.trim(),
		fields: state.fields
	}), [
		state.title,
		state.description,
		state.fields
	]);
	const canSave = state.fields.length > 0 && state.title.trim().length > 0;
	return {
		title: state.title,
		description: state.description,
		fields: state.fields,
		selectedFieldId: state.selectedFieldId,
		canSave,
		...actions,
		getDefinition
	};
}
